"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["31813"],{37284(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.estrutura_formulario.item_fora_da_ordem_das_secoes","status":422,"titulo":"A ordem dos itens n\xe3o acompanha a ordem das se\xe7\xf5es"},"descricao":{"codigo":"uniplus.estrutura_formulario.item_fora_da_ordem_das_secoes","requisitos":[],"oQueAconteceu":["Os itens e os grupos do formul\xe1rio seguem a ordem das se\xe7\xf5es: um item de uma se\xe7\xe3o posterior nunca vem antes de um item de uma se\xe7\xe3o anterior. A confer\xeancia ordena itens e grupos pelo valor de `ordem` e compara a se\xe7\xe3o de cada um com a do anterior; a primeira invers\xe3o \xe9 recusada, e s\xf3 ela. A mensagem \xe9 \\"O item \'`{B\\\\}`\' vem depois de \'`{A\\\\}`\', mas est\xe1 numa se\xe7\xe3o anterior \xe0 dele.\\", em que `B` \xe9 o item fora de lugar e `A` o que o precede na ordem.","Na grava\xe7\xe3o dos itens e nos modelos, a recusa vem na lista `errors` da resposta, com `field` igual a `itens` (nos modelos de formul\xe1rio o `field` come\xe7a por `conteudo.`). Na grava\xe7\xe3o do formul\xe1rio do processo, a recusa vem quando as p\xe1ginas novas deixariam os itens j\xe1 gravados fora da ordem, e o `field` \xe9 `paginas`. Nada \xe9 gravado.","Esta confer\xeancia s\xf3 ocorre depois da de se\xe7\xe3o: se algum item ou grupo est\xe1 sem se\xe7\xe3o, ou numa se\xe7\xe3o que n\xe3o existe, \xe9 a recusa de [item fora de se\xe7\xe3o](/erros/uniplus.estrutura_formulario.item_fora_de_secao) que sai, e esta fica de fora. Nos modelos de formul\xe1rio, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Reordene os itens (`ordem`) para que os da primeira se\xe7\xe3o venham antes dos da segunda, e assim por diante, ou mude a `ordem` das p\xe1ginas, ou a se\xe7\xe3o (`paginaCodigo`) do item citado. Depois disso, grave de novo."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio","Grava\xe7\xe3o do formul\xe1rio do processo"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Estrutura formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);